import React from 'react';
import { PlusCircle, Edit3, Wrench, Radio, Sparkles, Clock, ListChecks, Plus } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const ActivityFeed = ({ activities = [] }) => {
  const navigate = useNavigate();

  // Fallback 4 rich audit activity items
  const defaultActivities = [
    {
      id: 'act-101',
      type: 'added',
      machineId: 'LOOM-101',
      assetName: 'Toyota Air Jet Alpha',
      details: 'Registered in Digital Twin Asset Inventory • Telemetry Stream Active',
      user: 'Anita Desai',
      timestamp: new Date(Date.now() - 1000 * 60 * 10).toISOString(),
    },
    {
      id: 'act-102',
      type: 'maintenance',
      machineId: 'LOOM-201',
      assetName: 'Dornier Heavy Shuttleless',
      details: 'Drive shaft bearing overhaul scheduled for preventive maintenance',
      user: 'Suresh Mehta',
      timestamp: new Date(Date.now() - 1000 * 60 * 35).toISOString(),
    },
    {
      id: 'act-103',
      type: 'sensor',
      machineId: 'LOOM-301',
      assetName: 'Itema A9500 Denim',
      details: '136 IoT telemetry transducer feeds synchronized with MQTT broker',
      user: 'System Engineer',
      timestamp: new Date(Date.now() - 1000 * 60 * 65).toISOString(),
    },
    {
      id: 'act-104',
      type: 'prediction',
      machineId: 'LOOM-501',
      assetName: 'Picanol OmniPlus i',
      details: 'AI RUL Model flagged thermal anomaly (>64°C) with 99.4% confidence',
      user: 'AI RUL Engine',
      timestamp: new Date(Date.now() - 1000 * 60 * 120).toISOString(),
    },
  ];

  const itemsToDisplay = activities && activities.length > 0 ? activities.slice(0, 4) : defaultActivities;

  const getIcon = (type) => {
    switch (type) {
      case 'added':
        return <PlusCircle size={16} style={{ color: 'var(--status-running)' }} />;
      case 'maintenance':
        return <Wrench size={16} style={{ color: 'var(--status-idle)' }} />;
      case 'sensor':
        return <Radio size={16} style={{ color: 'var(--accent-primary)' }} />;
      case 'prediction':
        return <Sparkles size={16} style={{ color: 'var(--status-maintenance)' }} />;
      default:
        return <Clock size={16} style={{ color: 'var(--accent-primary)' }} />;
    }
  };

  const getBadgeColor = (type) => {
    switch (type) {
      case 'added':
        return 'var(--status-running)';
      case 'maintenance':
        return 'var(--status-idle)';
      case 'prediction':
        return 'var(--status-maintenance)';
      default:
        return 'var(--accent-primary)';
    }
  };

  const formatTime = (isoString) => {
    if (!isoString) return 'Just now';
    const date = new Date(isoString);
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) + ' - ' + date.toLocaleDateString();
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%', justifyContent: 'space-between' }}>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.6rem' }}>
        {itemsToDisplay.map((item, index) => (
          <div
            key={item.id || index}
            style={{
              display: 'flex',
              alignItems: 'flex-start',
              gap: '0.75rem',
              padding: '0.65rem 0.85rem',
              borderRadius: 'var(--radius-sm)',
              background: 'var(--bg-primary)',
              border: '1px solid var(--border-subtle)',
            }}
          >
            <div style={{ marginTop: '2px', flexShrink: 0 }}>{getIcon(item.type)}</div>
            <div style={{ flex: 1 }}>
              <div style={{ fontSize: '0.86rem', color: 'var(--text-primary)', fontWeight: '800' }}>
                <span
                  style={{
                    color: getBadgeColor(item.type),
                    textTransform: 'capitalize',
                    marginRight: '6px',
                    fontWeight: '800',
                  }}
                >
                  {item.type}
                </span>
                {item.assetName || item.machineId}
                <span style={{ color: 'var(--accent-primary)', fontSize: '0.78rem', fontWeight: '800', marginLeft: '5px', fontFamily: 'JetBrains Mono, monospace' }}>
                  ({item.machineId})
                </span>
              </div>

              {/* Details */}
              <div style={{ fontSize: '0.76rem', color: 'var(--text-secondary)', marginTop: '2px', fontWeight: '600' }}>
                {item.details || item.description || 'Registered in Digital Twin Asset Inventory • Telemetry Stream Active'}
              </div>

              <div style={{ fontSize: '0.72rem', color: 'var(--text-muted)', marginTop: '4px', display: 'flex', gap: '0.4rem', alignItems: 'center', fontWeight: '600' }}>
                <span>By {item.user || 'System Engineer'}</span>
                <span>•</span>
                <span>{formatTime(item.timestamp)}</span>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Action Footer */}
      <div style={{ display: 'flex', gap: '0.5rem', marginTop: '0.75rem' }}>
        <button
          onClick={() => navigate('/assets')}
          className="btn btn-secondary btn-sm"
          style={{ flex: 1, justifyContent: 'center', fontSize: '0.76rem', fontWeight: '700' }}
        >
          <ListChecks size={14} style={{ color: 'var(--accent-primary)' }} /> Audit Logs
        </button>
        <button
          onClick={() => navigate('/assets/new')}
          className="btn btn-primary btn-sm"
          style={{ flex: 1, justifyContent: 'center', fontSize: '0.76rem', fontWeight: '700' }}
        >
          <Plus size={14} /> Add Asset
        </button>
      </div>
    </div>
  );
};

export default ActivityFeed;
